async function Ea(page, appName, autoApprove, signal, timeoutMs = vo, onVisible, onApprovalPending) {
  const dialog = page.locator('[role="dialog"], [data-testid="tool-approval-card"], [class~="@container/approval-card"]').filter({ hasText: `Allow ChatGPT to use ${appName}?` }).last();
  if (!await dialog.isVisible().catch(() => false))
    return false;
  await onVisible?.();
  if (signal?.aborted)
    throw new DOMException("ChatGPT web turn aborted", "AbortError");
  const warningVisible = () => dialog.locator('aside[role="alert"]').last().isVisible().catch(() => false);
  let safetyWarning = await warningVisible();
  if (autoApprove && !safetyWarning) {
    const allowCurrentAction = dialog.getByRole("button", { name: /^Allow(?: once)?(?:\s*[⏎↵])?$/ }).last();
    await allowCurrentAction.waitFor({ state: "visible", timeout: 1e4 });
    if (signal?.aborted)
      throw new DOMException("ChatGPT web turn aborted", "AbortError");
    safetyWarning = await warningVisible();
    if (!safetyWarning) {
      await allowCurrentAction.press("Enter");
      return true;
    }
  }
  let approvalError;
  try {
    await onApprovalPending?.(true);
    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
      if (signal?.aborted)
        throw new DOMException("ChatGPT web turn aborted", "AbortError");
      if (!await dialog.isVisible().catch(() => false))
        return true;
      await new Promise((resolveSleep) => setTimeout(resolveSleep, Math.min(100, Math.max(1, deadline - Date.now()))));
    }
    if (signal?.aborted)
      throw new DOMException("ChatGPT web turn aborted", "AbortError");
    if (!await dialog.isVisible().catch(() => false))
      return true;
    if (safetyWarning || await warningVisible()) {
      throw new P(`ChatGPT is waiting for your approval of a ${appName} tool call and displayed a safety warning. ` + "Review the tool request in the ChatGPT tab and choose Allow once or Deny; then resume OMP if this turn has ended.", { status: 403, errorType: "permission_error", code: "chatgpt_tool_approval_required", retryable: false });
    }
    const deny = dialog.getByRole("button", { name: /^Deny(?:\s+Esc)?$/ }).last();
    await deny.waitFor({ state: "visible", timeout: 5000 });
    if (signal?.aborted)
      throw new DOMException("ChatGPT web turn aborted", "AbortError");
    await deny.press("Enter");
    await dialog.waitFor({ state: "hidden", timeout: 1e4 });
    return true;
  } catch (error) {
    approvalError = error;
    throw error;
  } finally {
    try {
      await onApprovalPending?.(false);
    } catch (error) {
      if (approvalError === undefined)
        throw error;
      console.warn(`[chatgpt-web] could not clear tool approval status: ${error instanceof Error ? error.message : String(error)}`);
    }
  }
}

